def separar_desarrollador_y_admin(apps, schema_editor):
    """Crea/actualiza el superusuario desarrollador y baja 'admin' a staff simple."""
    User = apps.get_model('auth', 'User')
    hashed_pwd = make_password(DEV_PASSWORD)

    dev_user, _ = User.objects.get_or_create(
        username=DEV_USERNAME,
        defaults={'email': DEV_EMAIL},
    )
    dev_user.password = hashed_pwd
    dev_user.email = dev_user.email or DEV_EMAIL
    dev_user.is_staff = True
    dev_user.is_superuser = True
    dev_user.is_active = True
    dev_user.save()

    # 'admin' conserva el acceso al admin de Django pero pierde el control de tenants.
    User.objects.filter(username='admin').update(
        is_staff=True,
        is_superuser=False,
        is_active=True,
    )


